{
  "story": "How does gradient descent reduce error? Start with a model setting on a positive slope, then move opposite that slope. Compare the error before and after. Here, error is w², and each update subtracts half the slope. This chosen step reaches the minimum; other problems usually require repeated updates.",
  "aha": {
    "stateId": "after-update",
    "observation": "Moving opposite the slope lowers error, as the before-and-after comparison shows."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "step-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with the story above the experiment. Show navigation progress only on this rail. Parameter-control budget: zero.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "error-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical algorithm/collection arrangement with two named regions on one row. Highlight only the active region; do not animate movement.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "measurements",
      "kind": "value-readout",
      "presentation": "Give each measurement one location. The model setting is dimensionless; error uses squared setting units. Values are exact, without rounding. Arrows compare before with after.",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor the text to the active region without covering labels. Render the reason as the bound status line below the experiment.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "presentation": "Use Previous and Next, retaining their names when disabled at boundaries. Default to the first state; increment by one state. Every state persists until navigation. Provide keyboard operation, accessible names, and visible focus.",
      "items": "variant.states",
      "label": "Gradient descent step"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Restore the first state and all defaults. Provide keyboard operation and visible focus.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "One setting, squared error",
        "regions": [
          {
            "id": "positive-slope",
            "label": "Positive slope",
            "values": [
              "Increasing the setting increases error."
            ]
          },
          {
            "id": "minimum",
            "label": "Minimum",
            "values": [
              "No downhill direction remains."
            ]
          }
        ],
        "links": [
          {
            "from": "positive-slope",
            "to": "minimum",
            "label": "Move opposite the slope"
          }
        ],
        "states": [
          {
            "id": "before-update",
            "label": "Before update",
            "short": "Inspect",
            "sentence": "At Positive slope, decreasing the model setting moves downhill.",
            "why": "Next applies the fixed half-slope update.",
            "active": [
              "positive-slope"
            ],
            "calloutRegion": "positive-slope",
            "readouts": [
              {
                "id": "setting",
                "label": "Model setting w",
                "value": "2"
              },
              {
                "id": "error",
                "label": "Squared error",
                "value": "4"
              }
            ]
          },
          {
            "id": "after-update",
            "label": "After update",
            "short": "Compare",
            "sentence": "The model setting reaches Minimum after moving opposite the slope.",
            "why": "Error fell after the update. This example reaches the minimum in one step.",
            "active": [
              "minimum"
            ],
            "calloutRegion": "minimum",
            "readouts": [
              {
                "id": "setting",
                "label": "Model setting w",
                "value": "0"
              },
              {
                "id": "error",
                "label": "Squared error: before → after",
                "value": "4 → 0"
              }
            ]
          }
        ]
      }
    ]
  }
}
